import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import type { TerminalCard as TerminalCardOverlay } from "../EditPlan";

const MONO =
  'ui-monospace, SFMono-Regular, "Cascadia Mono", Consolas, "Liberation Mono", monospace';

/**
 * A command and its output, styled rather than screen-captured.
 *
 * Filming a terminal window gives you font smoothing artefacts at whatever
 * size the window happened to be; this renders at frame resolution and stays
 * legible after the GIF pass.
 *
 * Not auto-generated by demodraft — add it to an edit plan when a demo needs
 * to show a test run or a command alongside the UI.
 */
export const TerminalCard: React.FC<{
  card: TerminalCardOverlay;
  durationInFrames: number;
}> = ({ card, durationInFrames }) => {
  const frame = useCurrentFrame();
  const { fps, height, width } = useVideoConfig();

  const pop = spring({ frame, fps, config: { damping: 18, mass: 0.7 } });
  const fadeOut = interpolate(
    frame,
    [durationInFrames - Math.round(fps * 0.35), durationInFrames],
    [1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" },
  );
  const opacity = pop * fadeOut;

  const fontSize = Math.min(height * 0.028, (width * 0.62) / 46);
  const lineHeight = fontSize * 1.5;
  const pad = height * 0.03;

  // Output types out line by line, so the card reads as a run in progress
  // rather than a static screenshot.
  const revealed = Math.floor(
    interpolate(frame, [0, durationInFrames * 0.55], [0, card.output.length], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }),
  );

  return (
    <AbsoluteFill
      style={{
        justifyContent: "center",
        alignItems: "center",
        backgroundColor: `rgba(0,0,0,${0.55 * opacity})`,
      }}
    >
      <div
        style={{
          opacity,
          transform: `translateY(${(1 - pop) * height * 0.04}px)`,
          maxWidth: "84%",
          minWidth: "46%",
          backgroundColor: "#0d1117",
          border: "1px solid #30363d",
          borderRadius: height * 0.018,
          boxShadow: "0 24px 64px rgba(0,0,0,0.6)",
          overflow: "hidden",
        }}
      >
        <div
          style={{
            display: "flex",
            gap: height * 0.012,
            alignItems: "center",
            padding: `${pad * 0.45}px ${pad}px`,
            borderBottom: "1px solid #21262d",
            backgroundColor: "#161b22",
          }}
        >
          {["#ff5f57", "#febc2e", "#28c840"].map((c) => (
            <div
              key={c}
              style={{
                width: height * 0.016,
                height: height * 0.016,
                borderRadius: "50%",
                backgroundColor: c,
              }}
            />
          ))}
        </div>

        <div style={{ padding: `${pad * 0.7}px ${pad}px` }}>
          <div
            style={{
              fontFamily: MONO,
              fontSize,
              lineHeight: `${lineHeight}px`,
              color: "#e6edf3",
              whiteSpace: "pre",
            }}
          >
            <span style={{ color: "#56d364" }}>$ </span>
            {card.command}
          </div>
          {card.output.slice(0, revealed).map((line, i) => (
            <div
              key={i}
              style={{
                fontFamily: MONO,
                fontSize,
                lineHeight: `${lineHeight}px`,
                color: "#8b949e",
                whiteSpace: "pre",
              }}
            >
              {line.length > 0 ? line : " "}
            </div>
          ))}
        </div>
      </div>
    </AbsoluteFill>
  );
};
